["Collect 15 Partially Digested Journal Pages from the Shaper's Terrace."]="在塑造者露台收集 15 页被部分消化的日记残页。",
["Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there."]="进入奥卡兹监狱，从人类守卫身上收集 8 条血红头巾。",
["Enter Alcaz Prison and learn what became of the King of Stormwind."]="进入奥卡兹监狱，查明暴风城国王的下落。",
["Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara."]="进入黑喉要塞，找回 5 个黑喉袋包，交给艾萨拉埃达拉斯废墟的埃卡尔。",
["Enter the Alcaz Prison and find Commander Folkar."]="进入奥卡兹监狱，找到指挥官福尔卡。",
["Enter the Alcaz Prison and slay 15  Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary."]="进入奥卡兹监狱，击杀 15 名 Strashasz 士兵和 8 名 Strashaz 女妖术师，并将潮汐主母卡扎丝的头颅交给萨莉·麦克利里。",
["Enter the Alcaz Prison and slay 15 Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka."]="进入奥卡兹监狱，击杀 15 名 Strashasz 士兵和 8 名 Strashaz 女妖术师，并将潮汐主母卡扎丝的头颅交给乌尔卡中士。",
["Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each."]="在塑造者露台寻找值得注意的地标，并在每处填写探险者地图。",
["Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan."]="在黑喉要塞找到乌索克图腾和乌索尔图腾，将它们交还给乌索兰的博学者诺克。",
["Gather 8 Seeping Slime Essence in the Shaper's Terrace."]="在塑造者露台收集 8 份渗出软泥精华。",
["Gather a colorless Drained Crystal Fragment near the Achromatic Crystal in the Shaper's Terrace."]="在塑造者露台的无色水晶附近收集一块无色的枯竭水晶碎片。",
["Look for King Varian Wrynn in Alcaz Prison."]="在奥卡兹监狱寻找瓦里安·乌瑞恩国王。",
["Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison."]="从奥卡兹监狱的审问者身上取得奥卡兹镣铐钥匙。",
["Report to the Image of Archmage Modera near the City of Dalaran."]="向达拉然城附近的大法师莫德拉的影像报到。",
["Slay 6 Ravasaur Matriarchs, 9 Ironhide Ravasaurs and Venomridge in Shaper's Terrace."]="在塑造者露台击杀 6 只暴掠龙母、9 只铁皮暴掠龙和 Venomridge。",
["Speak to Archmage Celindra in the City of Dalaran."]="与达拉然城中的大法师塞琳德拉交谈。",
["Travel to Blackmaw Hold in Kalimdor, and recover the Reliquary of Tyr."]="前往卡利姆多的黑喉要塞，取回提尔的圣物匣。",
