-- QuestieDB objective translations matched by quest ID and exact original text.
["Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge."]="将15份冬泉谷血样、20枚金币以及一副野性之心护腕交给铁炉堡的德莉亚娜。",
["Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="收集4份健康的野鹿腺体，把它们交给艾萨拉的奥汀克。奥汀克住在埃达拉斯废墟东北部悬崖的顶部。",
["Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="为艾萨拉的奥汀克带回一份亡灵腐液。奥汀克住在埃达拉斯废墟东北部悬崖的顶端。",
["Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar."]="从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。",
["Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull."]="安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。",
["Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready."]="成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。",
["Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready."]="成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。",
["Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom."]="为雷霆崖的药剂师扎玛收集10朵毒蛇花。",
["Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs."]="大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。",
["Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity."]="帮幽暗城的大药剂师法拉尼尔带回一堆沼泽蝙蝠的粪便。",
["Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."]="把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。",
["Bring 10 Encoded Fragments to Archmage Xylem in Azshara."]="将10块密文碎片交给艾萨拉的大法师克希雷姆。",
["Bring 10 Glittering Dust to Archmage Xylem."]="为大法师克希雷姆收集10份闪光尘埃。",
["Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."]="将10块腐烂的木头和4个血毒精华交给费伍德森林的伊普斯。",
["Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus."]="收集10个暮光坠饰，把它们交给达纳苏斯的银月守卫玛纳杜斯。",
["Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge."]="收集12个基础模组，把它们交给铁炉堡的科劳莫特·钢尺。",
["Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar."]="收集12颗紫色蘑菇，把它们交给塞尔萨玛的加克。",
["Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath."]="收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。",
["Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands."]="将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。",
["Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands."]="将15块骸骨碎片交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
["Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale."]="收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。",
["Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan."]="收集20瓶巨魔调和剂，把它们交给加基森的特伦顿·轻锤。",
["Bring 3 Arcanite Bar to Gorzeeki in the Burning Steppes."]="把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。",
["Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes."]="把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。",
["Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."]="把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。",
["Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul."]="把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。",
["Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan."]="收集4个雕纹石罐，把它们交给洛克莫丹的勘察员基恩萨·铁环。",
["Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths."]="将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。",
