["Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."]="前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。",
["Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan."]="给加基森的特兰雷克带去5个完整的圣甲虫壳。",
