["Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="将6块碎浪多头怪的鳞片交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶部。",
["Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet."]="收集6份哀嚎香精，把它们交给棘齿城的麦伯克·米希瑞克斯。",
["Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp."]="给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。",
["Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads."]="收集8块变异的钳嘴龟壳，把它们交给十字路口的图加。",
