["Bring 8 Thorium Plated Daggers to Kalaran Windblade."]="给卡拉然带去8把瑟银匕首。",
["Bring 8 Uncracked Chillwind Horns to Felnok Steelspring."]="将8支完整的冰风奇美拉角交给菲诺克。",
["Bring Ambassador Malcin's Head to Varimathras in the Undercity."]="把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。",
