["Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus."]="将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。",
["Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection."]="将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。",
["Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity."]="将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。",
["Bring a Lieutenant's Insignia to Thrall in Orgrimmar."]="将军官的徽章交给奥格瑞玛的萨尔。",
["Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge."]="将彩色穿孔卡片交给铁炉堡的大机械师卡斯派普。",
["Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp."]="给格罗姆高营地里的肯维雷带回一块石板碎片。",
["Bring a Venom Bottle to an apothecary in Tarren Mill."]="将毒药瓶交给塔伦米尔的某个药剂师。",
["Bring a Wildheart Belt and a set of Wildheart Gloves Deliana in Ironforge."]="将一条野性之心腰带和一副野性之心手套交给铁炉堡的德莉亚娜。",
["Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."]="将一副完好的苔蹄快步者鹿角交给艾萨拉的奥汀克。奥汀克居住在埃达拉斯废墟东北部的悬崖顶。",
["Bring a piece of felcloth to Impsy in Felwood."]="将一块恶魔布交给费伍德森林的伊普斯。",
["Bring a total of 6 Voodoo Feathers from the trolls in sunken temple."]="到沉没的神庙去，从巨魔们身上获得6支巫毒羽毛。",
["Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
["Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."]="给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。",
