["Bring five silver bars to Talvash del Kissel in Ironforge."]="给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。",
["Bring the Ancient Egg to Yeh'kinya in Tanaris."]="将远古之卵交给塔纳利斯的叶基亚。",
["Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind."]="将阿塔莱石板碎片交给暴风城的布罗哈恩·铁桶。",
["Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity."]="把乌尔之书交给幽暗城炼金区里的看守者贝尔杜加。",
["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar."]="将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给奥格瑞玛的诺格。",
["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge."]="将闪亮的金戒指、1块银锭、1块绿玛瑙和30个银币交给铁炉堡的塔瓦斯德·基瑟尔。",
["Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands."]="将一捆阿塔莱神器交给辛特兰的阿塔莱流放者。",
["Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes."]="把血箱交给燃烧平原的戈瑟奇·邪眼。",
["Bring the Damp Note to Je'neu Sancrea in Ashenvale."]="把潮湿的便笺交给灰谷的耶努萨克雷。",
["Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath."]="将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。",
