["Bring the Extra-Dimensional Ghost Revealer to Deliana in Ironforge."]="将超维度幽灵显形器交给铁炉堡的德莉亚娜。",
["Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."]="把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。",
["Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris."]="将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
["Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris."]="将装满的哈卡之卵交给塔纳利斯的叶基亚。",
["Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris."]="将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。",
["Bring the Frozen Eggs to Betina Bigglezink."]="将冰冻的龙蛋交给贝蒂娜·比格辛克。",
["Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands."]="把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。",
["Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff."]="将考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石交给雷霆崖的纳拉·蛮鬃。",
["Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands."]="把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂中的贝蒂娜·比格辛克。",
["Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."]="把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。",
["Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan."]="把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。",
["Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes."]="把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。",
["Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."]="将惰性天灾石交给冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",
["Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge."]="把洛迦里斯手稿带给铁炉堡的葛利·硬骨。",
["Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos."]="把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。",
["Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath."]="把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。",
["Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise."]="把噩梦碎片交给长者高地的哈缪尔·符文图腾。",
["Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus."]="把噩梦碎片交给达纳苏斯的玛斯雷·驭熊者。",
["Bring the Sealed Blood Container to Mux Manascrambler inside Gadgetzan in Tanaris."]="将封起来的血液容器交给加基森的穆克斯·玛纳斯卡波。",
["Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."]="把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。",
["Bring the Tablet of Ryun'eh to Theldurin the Lost."]="把雷乌纳石板带给迷失者塞尔杜林。",
["Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris."]="把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
["Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh."]="将深渊皇冠交给尘泥沼泽的塔贝萨。",
["Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."]="将摩弗拉斯的牙齿交给艾萨拉的奥汀克。他住在埃达拉斯废墟东北部悬崖的顶端。",
["Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde."]="将你从沉没的神庙的巨魔身上得到的巫毒羽毛交给部落英雄的灵魂。",
["Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity."]="将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。",
["Bring the head of Targorr the Dread to Guard Berton in Lakeshire."]="把塔格尔的头颅带给湖畔镇的卫兵伯尔顿。",
["Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff."]="把梦游者克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。",
["Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus."]="把梦游者克尔里斯的头颅交给达纳苏斯的哨兵塞尔高姆。",
["Bring the pieces for the spirit totem to Bath'rah the Windwatcher."]="将灵魂图腾所需的材料交给捕风者巴斯拉。",
["Bring the voodoo feathers to Ashlam Valorfist."]="前往沉没的神庙，从巨魔守护者们身上取得巫毒羽毛，然后把它们交给阿什拉姆·瓦罗菲斯特。",
["Bring the voodoo feathers to Bath'rah the Windwatcher."]="将巫毒羽毛交给捕风者巴斯拉。",
["Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind."]="收集24副机械内胆，把它们交给暴风城的舒尼。",
["Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar."]="暴风城的布罗哈恩·铁桶要求你去找到阿塔哈卡神庙。",
["Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port."]="在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。",
["Check the cages at the two Witherbark villages, then return to Gryphon Master Talonaxe."]="检查两个枯木巨魔村落里的笼子，然后向狮鹫管理员沙拉克·鹰斧回复。",
["Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe."]="检查祖尔祭坛的顶部，然后向狮鹫管理员沙拉克·鹰斧报告。",
["Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."]="从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。",
["Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."]="从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。",
["Collect 15 Bloodpetals and return to Muigin."]="从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。",
["Collect 15 Theradric Crystal Carvings for Willow in Desolace."]="为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。",
["Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard."]="收集20个哈卡神像，把它们带给斯通纳德的费泽鲁尔。",
["Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."]="收集20个爪牙的天灾石，并将它们交给西瘟疫之地的高阶牧师赛尔丹尼斯。",
["Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Kalaran Windblade."]="收集4份烈焰之心和4份傀儡之油，然后把这些东西交给卡拉然·温布雷。",
["Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."]="收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。",
["Collect 6 Enchanted Coral and return them to Archmage Xylem."]="收集6块魔化珊瑚，然后把它们交给大法师克希雷姆。",
["Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."]="收集一些血帽和格里什钉刺，然后向托尔瓦·寻路者复命。",
["Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."]="为捕风者巴斯拉收集一份空气样本、一份火元素样本、一份土元素样本和一份水元素样本。",
["Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar."]="找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。",
["Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward."]="夜色镇的米尔斯迪普议员要你杀死迪克斯特·瓦德，并把他的手带回来作为证明。",
["Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns."]="棘齿城的起重机操作员比戈弗兹让你从疯狂的马格利什那儿取回一瓶99年波尔多陈酿，疯狂的马格利什就藏在哀嚎洞穴里。",
["Defend Gor'shak."]="保护哥沙克。",
["Deliver Rexxar's Letter to Myranda the Hag in the Western Plaguelands."]="把雷克萨的证明交给西瘟疫之地的巫女麦兰达。",
["Deliver the Letter to the City Architect to Baros Alexston in Stormwind."]="将艾德温·范克里夫的信交给巴隆斯·阿历克斯顿。",
["Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge."]="收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。",
["Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point."]="杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。",
["Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands."]="杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地冰风岗的化学家阿尔比顿。",
["Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands."]="杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
["Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife."]="杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。",
["Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."]="哀嚎洞穴的厄布鲁要求你杀掉7只变异破坏者、7只剧毒飞蛇、7只变异蹒跚者和7只变异尖牙风蛇。",
["Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar."]="进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。",
["Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay."]="将克努比护送到出口，然后向藏宝海湾的斯库提汇报。",
["Escort Willix the Importer out of Razorfen Kraul."]="护送进口商威利克斯逃出剃刀沼泽。",
["Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information."]="护送迪菲亚叛徒前往迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。",
["Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts."]="斯通纳德的费泽鲁尔要求你收集10件阿塔莱神器。",
["Figure out a way to remove the grime from the Grime-Encrusted Ring."]="想方法把脏兮兮的戒指弄干净。",
["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens."]="找到3块索兰鲁克宝珠的碎片和1块索兰鲁克宝珠的大碎片，把它们交给贫瘠之地的杜安·卡汉。",
["Find Advisor Belgrum and give him his note."]="找到顾问贝尔格拉姆，把便笺交给他。",
["Find Agmond."]="找到阿戈莫德。",
["Find Baelog in Uldaman."]="在奥达曼找到巴尔洛戈。",
["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."]="找到连接石爪山和灰谷的石爪小径里的布劳格·幽魂。",
["Find Daphne Stilwell in Westfall."]="在西部荒野找到达芙妮·斯迪威尔。",
["Find Egan. You only know that he was last seen around Stratholme."]="找到埃根。你只知道他在斯坦索姆附近。",
["Find Hammertoe Grez in Uldaman."]="在奥达曼找到铁趾格雷兹。",
["Find Hammertoe's Amulet and return it to him in Uldaman."]="找到铁趾的护符，把它交给奥达曼的铁趾。",
["Find Lord Incendius in Blackrock Depths and destroy him!"]="在黑石深渊里找到伊森迪奥斯，然后把他干掉！",
["Find Magma Lord Bokk in the Burning Steppes, obtain his Magma Core and bring it to Mux Manascrambler in Gadgetzan."]="前往燃烧平原，找到熔岩领主博奥克，把它的岩浆核心交给加基森的穆克斯·玛纳斯卡波。",
["Find Marvon Rivetseeker in Tanaris."]="到塔纳利斯找到玛尔冯·瑞文斯克。",
["Find Parqual Fintallas in Undercity."]="找到幽暗城的帕科瓦·芬塔拉斯。",
["Find Prate Cloudseer in Thousand Needles."]="到千针石林去找普拉特·白云。",
["Find Prospector Ryedol and let him know Hammertoe Grez is alive."]="找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。",
["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."]="在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。",
["Find Starfall in Winterspring and speak with Wynd Nightchaser."]="找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。",
["Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity."]="找到《亡灵的起源》，把它交给幽暗城的帕科瓦·芬塔拉斯。",
["Find a clue as to the gems' whereabouts in the depths of Uldaman."]="在奥达曼里找寻宝石的线索。",
["Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus."]="将塔莎拉的坠饰带给达纳苏斯的塔莎拉·静水。",
["Find and return a Symbol of Ragnaros to Kalaran Windblade."]="找到一个拉格纳罗斯符记，把它交给卡拉然·温布雷。",
["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic."]="找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",
["Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."]="在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。",
["Find the 4 tablets and bring their legends back to Brother Nimetz."]="找到4块石板并将上面的内容带回去交给尼麦兹修士。",
["Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."]="在悲伤沼泽沉没的神庙中找到哈卡祭坛。",
["Find the Black Guard Swordsmith in Stratholme and destroy him. Recover the Insignia of the Black Guard and return to Seril Scourgebane."]="在斯坦索姆找到黑衣守卫铸剑师，然后杀死他。将黑色卫士徽记交给亡灵杀手瑟里尔。",
["Find the Deathstalker Adamant and Deathstalker Vincent."]="找到亡灵哨兵阿达曼特和亡灵哨兵文森特。",
["Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."]="在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。",
["Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."]="找到《巨龙的遗产》，把它还给位于灰谷和石爪山之间的石爪小径里的布劳格·幽魂。",
["Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."]="在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。",
["Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge."]="找到意志石板，把它们交给铁炉堡的顾问贝尔格拉姆。",
["Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill."]="找到被遗忘者的叛徒，取回他们偷走的神器，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。",
["Follow Reginald Windsor through Stormwind. Protect him from harm!"]="跟随雷吉纳德·温德索尔元帅在暴风城中前进。保护他，别让他受到伤害！",
["Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind."]="为暴风城的布罗哈恩·铁桶收集10块阿塔莱石板。",
["Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet."]="从赤鳞镰爪龙身上收集5根完整的迅猛龙角，把它们交给棘齿城的米希瑞克斯。",
["Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems."]="奥伯丁的戈沙拉·夜语需要8块堕落者的脑干。",
["Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."]="到奥达曼的北部大厅去找到克罗姆·粗臂的箱子，从里面拿出他的宝贵财产，然后回到铁炉堡把东西交给他。",
["Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."]="从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。",
["Give Marshal Maxwell the bad news."]="把这个坏消息传达给麦克斯韦尔元帅。",
["Give Tinkee's Letter to Felnok Steelspring."]="把丁奇的信交给菲诺克。",
["Give the Dull and Flat Elven Blade to Lorekeeper Lydros."]="把黯淡的精灵剑交给博学者莱德罗斯。",
["Go into Stratholme and rescue Ysida Harmon from Baron Rivendare."]="进入斯坦索姆，从瑞文戴尔男爵手中救出伊思达。",
["Gryan Stoutmantle wants you to talk to Wiley in Lakeshire."]="格里安·斯托曼要求你去和湖畔镇的威利谈一谈。",
["Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife."]="诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。",
["Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed."]="帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。",
["Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."]="为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。",
["If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."]="如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。",
["If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."]="如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。",
["If you have faith, leap from the planks overlooking Thousand Needles."]="如果你有坚定的信仰，就从那个可以俯瞰千针石林的木板跳下去。",
["In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Chances are good that you will have to kill her as well. Return to Ragged John when you are poisoned so that he can 'milk' you."]="你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。",
["Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine."]="将脏兮兮的东西放入超级清洁器5200型，记得要用三枚银币来启动机器。",
["It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."]="看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。",
["Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands."]="杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。",
["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."]="杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。",
["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill."]="杀掉6个达拉然召唤师和12个元素奴仆，然后回到塔伦米尔去见大法师沃迪恩·伍德格莱尔。",
["Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde."]="杀死7头地狱野猪，然后回到部落英雄的灵魂那儿。",
["Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp."]="杀死8个可怕的血僵尸和8个游荡的幽灵，然后向亡灵卫兵林奈汇报。",
["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."]="杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。",
["Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge."]="杀死苦痛堡垒中的因弗努斯大使，把证明他已死亡的信物交给铁炉堡的顾问贝尔格拉姆。",
["Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher."]="杀死阿鲁高，把他的头带给瑟伯切尔的达拉尔·道恩维沃尔。",
["Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade."]="杀死巴基尔·斯瑞德，把他的头带给监狱的典狱官塞尔沃特。",
["Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar."]="杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。",
["Kill Edwin VanCleef and bring his head to Gryan Stoutmantle."]="杀死艾德温·范克里夫，把他的头交给格里安·斯托曼。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."]="杀死大检察官怀特迈恩，血色十字军指挥官莫格莱尼，十字军的勇士赫洛德和驯犬者洛克希并向南海镇的莱雷恩复命。",
["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."]="杀掉大检察官怀特迈恩、血色十字军指挥官莫格莱尼、血色十字军勇士赫洛德和驯犬者洛克希，然后向幽暗城的瓦里玛萨斯回报。",
["Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale."]="杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。",
["Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows."]="前往沉没的阿塔哈卡神庙，杀死绿龙摩弗拉斯，将他的血液交给费伍德森林中的格雷塔·苔蹄。沉没的神庙的入口就在悲伤沼泽中。",
["Kill the Demon of the Orb, then speak with Tabetha."]="杀死宝珠之魔，然后与塔贝萨谈一谈。",
["Let Jarkal borrow the necklace. In exchange, he will translate the journal for you."]="将项链借给加卡尔。作为交换，他将帮你翻译日记。",
["Listen as Kalaran Windblade tells his story."]="听卡拉然·温布雷讲述他的故事。",
["Listen to Royal Historian Archesonus recant the history of Thaurissan."]="听皇家历史学家阿克瑟努斯讲述索瑞森的历史。",
["Listen to Thrall."]="听萨尔讲话。",
["Listen to what Tirion Fordring has to say."]="听听提里奥·弗丁要说什么。",
["Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."]="在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。",
["Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."]="在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。",
["Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal."]="幽暗城的大药剂师法拉尼尔需要20颗狂热之心。",
["Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves, 5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists."]="丹莫德的莫特雷·加玛森要求你杀死15名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。",
["Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr."]="丹莫德的莫特雷·加玛森要求你把卡姆·深怒的头颅交给他。",
["Nalpak in the Wailing Caverns wants 20 Deviate Hides."]="哀嚎洞穴的纳尔帕克想要20张变异皮革。",
["Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas."]="暴风城的尼科瓦·拉斯克要你取得10条红色毛纺面罩。",
["Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor."]="为米奈希尔港口的詹姆斯·哈洛兰带回4张小鳄鱼皮。",
["Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge."]="从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。",
["Open the chest."]="打开箱子。",
["Place Dawn's Gambit in the Viewing Room of the Scholomance. Defeat Vectus, then return to Betina Bigglezink."]="将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。",
["Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple."]="把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。",
["Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes."]="从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。",
["Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike."]="阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。",
["Read Henrig Lonebrow's Journal."]="阅读亨里格·独眉的日记。",
["Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."]="阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。",
["Read Warosh's Scroll. Bring Warosh's Mojo to Warosh."]="阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。",
["Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin."]="阅读塞卡石板，了解枯木巨魔的蜘蛛之神的名字，然后回到加德林大师那里。",
["Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace."]="阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。",
["Recover 10 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."]="从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……",
["Report back to Tonga Runetotem with your findings."]="向图加·符文图腾报告你的发现。",
["Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind."]="给暴风城的维尔德·蓟草带回4张矿业工会会员卡。",
["Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge."]="从修道院拿回《泰坦神话》，把它交给铁炉堡的图书馆员麦伊·苍尘。",
["Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder."]="从沉没的神庙底部的守卫身上得到一些腐烂藤蔓，把它们交给托尔瓦·寻路者。",
["Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh."]="找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。",
["Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem."]="从摩弗拉斯身上取回奥术碎片，然后返回大法师克希雷姆那儿。",
["Retrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff."]="从血色修道院里找到《堕落者纲要》，把它交给雷霆崖的圣者图希克。",
["Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind."]="从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。",
["Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara."]="从艾萨拉的木喉萨满祭司那儿取回密封的蓝袋子，将它交给艾萨拉的大法师克希雷姆。",
["Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."]="到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。",
["Return Foror's Compendium of Dragon Slaying to the Athenaeum."]="将《诺斯特罗的屠龙技术纲要》还回图书馆。",
["Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill."]="把沃瑞尔·森加斯的结婚戒指还给塔伦米尔的莫尼卡·森古特斯。",
["Return the Azure Key to Lord Jorach Ravenholdt."]="将碧蓝钥匙交给乔拉齐·拉文霍德公爵。",
["Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
["Return the book to its rightful owners."]="将这本典籍交给它的主人。",
["Return to Fel'Zerul in Stonard."]="向斯通纳德的费泽鲁尔回报。",
["Return to Ironforge and deliver the bad news to King Magni Bronzebeard."]="回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。",
["Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."]="回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。",
["Return to Mux Manascrambler in Gadgetzan with 1 Delicate Arcanite Converter, 4 Greater Eternal Essence, 10 Stonescale Oil, 25 Volcanic Ash and 40 gold."]="将1个精密奥金转换器、4份强效不灭精华、10瓶石鳞鱼油、25份火山灰和40枚金币交给加基森的穆克斯·玛纳斯卡波。",
["Return to Tonga at The Crossroads, after investigating the Stagnant Oasis."]="调查死水绿洲，然后返回十字路口向图加·符文图腾报告。",
["Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!"]="返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！",
["Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
["Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers."]="辛特兰的拉普索迪·铁铲要求你带给他3块大鹏的砂囊、3块格罗多克猩猩的肝脏和3块铁鬃熊的肝脏。",
["Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas."]="给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。",
["Search Dire Maul for Kariel Winthalus. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find."]="到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。",
["Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find."]="到厄运之槌去寻找泰尔米乌斯·探梦者。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。",
["Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff."]="在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。",
["Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest."]="在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。",
["Search for an imp inside a cave at the entrance of Darkwhisper Gorge in southern Winterspring, purchase a Fel Elemental Rod and return to Mux Manascrambler in Gadgetzan."]="到冬泉谷南部的暗语峡谷入口附近去，在那里的一处洞穴内的某个小鬼那里购买一根恶魔元素之杖，并把它交给加基森的穆克斯·玛纳斯卡波。",
["Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last."]="去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。",
["Search for the original creator of the shattered necklace to learn of its potential value."]="找到破碎的项链的来源，从而了解其潜在的价值。",
["Seek out Argent Guard Thaelrid in Blackfathom Deeps."]="到黑色深渊去找到银月守卫塞尔瑞德。",
["Seek out Commander Ashlam Valorfist. His base camp is located at Chillwind Camp, north of the Alterac Mountains."]="找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。",
["Seek out High Executor Derrington. His base camp is located at the Bulwark, east of Tirisfal Glade and the Undercity."]="找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。",
["Seek out Ogtinc in Azshara."]="找到艾萨拉的奥汀克。",
["Seek out Remulos in Moonglade and give him the Seed of Life."]="到月光林地去找到雷姆洛斯，将生命之种交给他。",
["Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas."]="按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。",
["Seek out Rhapsody Shindigger in The Hinterlands."]="去辛特兰找到拉普索迪·铁铲。",
["Seek out Sanath Lim-yo and gain passage to see Archmage Xylem."]="找到萨纳斯，让他将你传送到大法师克希雷姆那儿。",
["Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde."]="杀死诅咒之地的魔誓者，然后回到部落英雄的灵魂那儿。",
["Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete."]="杀掉15条黑色小龙、10条黑色龙人和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。",
["Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."]="杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。",
["Slay 30 Plaguebats and return to Tirion Fordring."]="杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。",
["Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."]="杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。",
["Slay Halycon, pack mistress of the Bloodaxe worg."]="杀死血斧座狼的领袖，哈雷肯。",
["Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."]="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。",
["Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace."]="杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。",
["Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace."]="杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。",
["Speak to Commander Ashlam Valorfist at Chillwind Camp."]="与冰风岗的指挥官阿什拉姆·瓦罗菲斯特谈一谈。",
["Speak to Dorn Plainstalker in Thousand Needles."]="和千针石林的多恩·平原行者谈一谈。",
["Speak to Duthorian Rall in Stormwind."]="与暴风城的达索瑞恩·拉尔谈一谈。",
["Speak to Historian Karnik."]="和史学家卡尼克谈一谈。",
["Speak to Je'neu Sancrea in Ashenvale."]="与灰谷的耶努萨克雷谈一谈。",
["Speak to Jordan Stilwell in Ironforge"]="去和铁炉堡的乔丹·斯迪威尔谈一谈。",
["Speak to Ogtinc in Azshara."]="跟艾萨拉的奥汀克谈一谈。",
["Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands."]="和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。",
["Speak with Apothecary Dithers at the Bulwark, Western Plaguelands."]="和西瘟疫之地亡灵壁垒的药剂师迪瑟斯谈一谈。",
["Speak with Brother Anton in Desolace."]="与凄凉之地的安东修士谈一谈。",
["Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major."]="如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。",
["Speak with Grimand Elmore in Stormwind's Dwarven District."]="与暴风城矮人区的格瑞曼德·艾尔默谈一谈。",
["Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary."]="与辛特兰的鹰巢山狮鹫饲养场里的狮鹫管理员沙拉克·鹰斧谈一谈。",
["Speak with Hamuul Runetotem."]="和哈缪尔·符文图腾谈一谈。",
["Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands."]="找到辛特兰的弗斯塔德·蛮锤。",
["Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."]="与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。",
["Speak with Jaron Stoneshaper in Starfall Village."]="与坠星村的加隆·石矛谈一谈。",
["Speak with Klockmort Spannerspan in Ironforge."]="与铁炉堡的科劳莫特·钢尺谈一谈。",
["Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas."]="和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。",
["Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District."]="与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。",
["Speak with Lord Jorach Ravenholdt in Ravenholdt Manor."]="前往拉文霍德庄园，和乔拉齐·拉文霍德公爵谈一谈。",
["Speak with Marshal Maxwell in the Burning Steppes."]="和燃烧平原的麦克斯韦尔元帅谈一谈。",
["Speak with Master Gadrin in Sen'jin Village."]="与森金村的加德林大师谈一谈。",
["Speak with Master Mechanic Castpipe in Ironforge."]="与铁炉堡的大机械师卡斯派普谈一谈。",
["Speak with Mayara Brightwing in the Burning Steppes."]="与燃烧平原的玛亚拉·布莱特文谈一谈。",
["Speak with Mor'zul Bloodbringer in the Burning Steppes."]="与燃烧平原的莫苏尔·召血者谈一谈。",
["Speak with Nara Wildmane."]="和纳拉·蛮鬃谈一谈。",
["Speak with Ozzie Togglevolt in Kharanos."]="与卡拉诺斯的奥齐·电环谈一谈。",
["Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan."]="和洛克莫丹铁环挖掘场的勘察员基恩萨·铁环谈一谈。",
["Speak with Ragnar Thunderbrew."]="和拉格纳·雷酒谈一谈。",
["Speak with Scooty in Booty Bay."]="和藏宝海湾的斯库提谈一谈。",
["Speak with Shadowmage Vivian Lagrave."]="与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
["Speak with Shadowmaster Vivian Lagrave in Kargath."]="与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
["Speak with Squire Maltrake."]="与侍卫玛特拉克谈一谈。",
["Speak with Tabetha in Dustwallow Marsh."]="与尘泥沼泽的塔贝萨谈一谈。",
["Speak with Tabetha."]="和塔贝萨谈一谈。",
["Speak with Talo Thornhoof at Camp Mojache in Feralas."]="和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。",
["Speak with Thrall if you are prepared to take on the mission he has planned."]="如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。",
["Speak with Tinkmaster Overspark in Ironforge."]="与铁炉堡的工匠大师欧沃斯巴克谈一谈。",
["Speak with Torwa Pathfinder in Un'Goro Crater."]="与安戈洛环形山的托尔瓦·寻路者谈一谈。",
["Speak with Tran'rek in Gadgetzan."]="与加基森的特兰雷克谈一谈。",
["Speak with Warden Thelwater in the Stockade."]="与监狱的典狱官塞尔沃特谈一谈。",
["Speak with Wizzle Brassbolts in the Shimmering Flats."]="和闪光平原的维兹尔·铜栓谈一谈。",
["Speak with Yuka Screwspigot in the Burning Steppes."]="与燃烧平原的尤卡·斯库比格特谈一谈。",
["Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon."]="和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。",
["Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."]="到诅咒之地的入口去，与部落英雄的灵魂谈一谈。",
["Stab a Devilsaur with the Devilsaur Barb. Return to Torwa Pathfinder in Un'Goro Crater when you have completed this task."]="将魔暴龙之刺扎入一只魔暴龙的体内。",
["Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood."]="费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。",
["Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."]="将安东修士的表彰信带给南海镇的虔诚的莱雷恩。",
["Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."]="把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。",
["Take Hammertoe's Amulet to Historian Karnik in Ironforge."]="把铁趾的护符交给铁炉堡的史学家卡尼克。",
["Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."]="把铁趾的护符交给荒芜之地的勘察员雷杜恩。",
["Take Shaw's report to Gryan Stoutmantle in Westfall."]="将肖尔的报告交给西部荒野的格里安·斯托曼。",
["Take Wiley's Note to Gryan Stoutmantle in Westfall."]="将威利的便笺交给西部荒野的格里安·斯托曼。",
["Take Wiley's Note to Mathias Shaw in Stormwind."]="将威利的便笺交给暴风城的马迪亚斯·肖尔。",
["Take a Bloodpetal to Gregan Brewspewer in Feralas."]="把血瓣花交给菲拉斯的格雷甘·山酒。",
["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."]="将恐怖图腾背包交给雷霆崖的拉哈罗。",
["Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."]="将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。",
["Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind."]="将奥妮克希亚的头颅交给暴风城的伯瓦尔·弗塔根公爵。",
["Take the Head of Onyxia to Thrall in Orgrimmar."]="将奥妮克希亚的头颅交给奥格瑞玛的萨尔。",
["Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar."]="将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。",
["Take the Small Scroll to Varimathras in the Undercity."]="把小卷轴交给幽暗城的瓦里玛萨斯。",
["Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."]="把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。",
["Take the Torch of Retribution."]="拿起惩戒火炬。",
["Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."]="把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。",
["Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."]="把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。",
["Talk to Malyfous Darkhammer in Everlook."]="与永望镇的玛雷弗斯·暗锤谈一谈。",
["The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an."]="辛特兰的阿塔莱流放者要你给他带回迦玛兰的头。",
["Track down the Defias Messenger in Westfall and bring his message to Stoutmantle."]="追捕西部荒野的迪菲亚信使，并将他身上携带着的信件交给斯托曼。",
["Travel into the Sunken Temple and discover the secret hidden in the circle of statues."]="到沉没的神庙去，揭开雕像群中隐藏的秘密。",
["Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."]="到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。",
["Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."]="到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。",
["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."]="到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。",
["Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."]="到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。",
["Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."]="到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。",
["Travel to Blackrock Spire and find out what happened to Bijou."]="到黑石塔去查明比修的下落。",
["Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."]="到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。",
["Travel to Blackrock Spire and slay Shadow Hunter Vosh'gajin. Recover Vosh'gajin's Snakestone and return to Kilram."]="到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。",
["Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."]="去黑石塔杀死大酋长雷德·黑手，带着他的头颅返回奥格瑞玛。",
["Travel to Gershala Nightwhisper in Auberdine."]="到奥伯丁的戈沙拉·夜语那儿去。",
["Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."]="到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。",
["Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."]="到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。",
["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."]="把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。",
["Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."]="到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。",
["Travel to Marvon Rivetseeker's workshop in Ratchet."]="到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。",
["Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."]="到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。",
["Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."]="到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。",
["Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived."]="前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。",
["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."]="在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。",
["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."]="到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。",
["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."]="到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。",
["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."]="到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。",
["Travel to Winterspring and find Haleh. Give her Awbee's scale."]="到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。",
["Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."]="到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。",
["Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."]="到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。",
["Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."]="到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。",
["Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."]="到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。",
["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."]="到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。",
["Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron."]="如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。",
["Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."]="使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。",
["Use the Ectoplasmic Distiller near incorporeal undead to collect 12 Scorched Ectoplasms in Silithus, 12 Frozen Ectoplasms in Winterspring and 12 Stable Ectoplasms in the Eastern Plaguelands. Bring them along with the Ectoplasmic Distiller back to Mux Manascrambler in Gadgetzan."]="使用灵质提纯器在希利苏斯收集12份烧焦的灵质，在冬泉谷收集12份冰冻的灵质，以及在东瘟疫之地收集12份稳定的灵质。然后将这些东西与灵质提纯器一起交给加基森的穆克斯·玛纳斯卡波。",
["Use the Eggscilloscope Prototype on an egg in the Rookery."]="在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。",
["Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos."]="用空铅瓶对着辐射入侵者或者辐射抢劫者，从它们身上收集放射尘。瓶子装满之后，把它交给卡拉诺斯的奥齐·电环。",
["Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."]="使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。",
["Use the Extra-Dimensional Ghost Revealer at the entrance to Stratholme and speak with the ghost of Anthion Harmon."]="在斯坦索姆的入口处使用超维度幽灵显形器，然后与安泰恩·哈尔蒙的灵魂交谈。",
["Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge."]="按照乔丹的武器材料单上的说明去寻找一些白石橡木、精炼矿石、乔丹的铁锤和一块科尔宝石，然后回到铁炉堡去见乔丹·斯迪威尔。",
["Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete."]="到诺莫瑞根去杀掉麦克尼尔·瑟玛普拉格。完成任务之后向大工匠梅卡托克报告。",
["Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."]="进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。",
["Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."]="到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。",
["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."]="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。",
["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."]="到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。",
["Wait for Scooty to calibrate the Goblin Transponder."]="等斯库提调整好地精传送器。",
["Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade."]="暴风城的典狱官塞尔沃特要求你杀死监狱中的10名迪菲亚囚徒、8名迪菲亚罪犯和8名迪菲亚叛军。",
["You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band."]="你要么自己留着这枚戒指，要么就按照戒指内侧刻着的名字找到它的主人。",
["You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."]="温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。",
["You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire."]="你必须从达基萨斯将军身上取回黑龙勇士之血，你可以在黑石塔的晋升大厅后面的房间里找到他。",
["You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist."]="你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。",
-- Try404 6.2.8 quest objectives; unknown proper names retained for client verification.
["Accompany Lumina Windsinger and help her escape Fenris Keep."]="陪同 Lumina Windsinger，帮助她逃离芬里斯城堡。",
["Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals. Once you have acquired enough mana, empower the pylons and return to Mordent Evenshade."]="从 Shen'dralas 的神殿取得法力筛，收集远古法力水晶。收集足够法力后为水晶塔注能，并返回 Mordent Evenshade 身边。",
["Bring 10 Motes of Unstable Magic to Archmage Celindra in Dalaran."]="将 10 份不稳定的魔法微粒交给达拉然的大法师 Celindra。",
["Bring 10 bottles of Silvermoon Shimmerwine to Arille Azuregaze in Dalaran city."]="将 10 瓶银月微光酒交给达拉然城的 Arille Azuregaze。",
["Bring Ott's Masterwork to Trevan Rol in Silverpine Forest."]="将奥特的杰作交给银松森林的 Trevan Rol。",
["Bring Thermaplugg's Engineering Notes to Nogg at the Valley of Honor in Orgrimmar."]="将瑟玛普拉格的工程学笔记交给奥格瑞玛荣誉谷的诺格。",
["Bring the Blackfathom Pearl to Bashana Runetotem in Thunder Bluff."]="将黑暗深渊珍珠交给雷霆崖的 Bashana Runetotem。",
["Bring the Blackfathom Pearl to Dawnwatcher Selgorm in Darnassus."]="将黑暗深渊珍珠交给达纳苏斯的 Dawnwatcher Selgorm。",
["Bring the Head of the Baron to the body of Othmar in the Undercity."]="将男爵的头颅带到幽暗城 Othmar 的遗体旁。",
["Bring the Orders from the Grand Crusader back to Katherine the Pure."]="将大十字军的命令带回给纯洁的 Katherine。",
["Bring the Satchel of Cursed Mementos to Ashe Amberhall in Farholde Keep."]="将诅咒纪念品袋交给 Farholde Keep 的 Ashe Amberhall。",
["Collect 'Rumi of Gnomeregan: The Collected Works' and bring it to Garion Wendell in Stormwind."]="收集《诺莫瑞根的鲁米：作品集》，交给暴风城的 Garion Wendell。",
["Collect 5 I'lalai Fetishes from trolls in the Drowned City."]="从沉没之城的巨魔身上收集 5 个 I'lalai 神像。",
["Collect 5 Twilight Pages from within Sunnyglade for Ashe Amberall in Farholde Keep."]="在 Sunnyglade 收集 5 页暮光文稿，交给 Farholde Keep 的 Ashe Amberhall。",
["Collect 7 Gnomeregan Archival Data cards from around Gnomeregan, then deliver them to Jemma Quikswitch in Ironforge."]="在诺莫瑞根各处收集 7 张档案数据卡，交给铁炉堡的 Jemma Quikswitch。",
["Collect 8 Cultist Bangles from the Twilight's Hammer in Krol'dok Stronghold."]="从克罗多克要塞的暮光之锤成员身上收集 8 个信徒腕环。",
["Collect Skullthumper from Klunk for Clugfist in Bolder'ok."]="从 Klunk 处取得 Skullthumper，交给 Bolder'ok 的 Clugfist。",
["Collect a Toxic Skullcap from Tawny Grisette in the Trade Quarter, Blisterweed near the Herbalism Trainer, and Essence of Agony from the poison vendor in the Rogues' Quarter for Master Apothecary Faranell in Undercity."]="在贸易区向 Tawny Grisette 收集有毒的盔帽，在草药学训练师附近收集泡叶草，在盗贼区的毒药商处取得痛苦精华，交给幽暗城的大药剂师法拉尼尔。",
["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."]="收集奥术微粒，交给达拉然城附近的大法师莫德拉的影像。",
["Convince a Twilight's Hammer miner in Sunnyglade to divulge their secrets."]="说服 Sunnyglade 的一名暮光之锤矿工透露秘密。",
["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Da'grosh."]="在 Twilight's Shroud 击败 8 名暮光狂热者、8 名暮光腐蚀者和 8 名暮光勇士，向 Da'grosh 复命。",
["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters, and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan."]="在 Twilight's Shroud 击败 8 名暮光狂热者、8 名暮光腐蚀者和 8 名暮光勇士，向 Riftan 中士复命。",
["Defeat 8 Twilight Raiders and 8 Twilight Neophytes within Sunnyglade for Tran'gul in Rog'mar."]="在 Sunnyglade 击败 8 名暮光袭击者和 8 名暮光新兵，向 Rog'mar 的 Tran'gul 复命。",
["Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans."]="击败剃刀沼泽的卡尔加·刺肋，收集有关野猪人计划的情报。",
["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Da'grosh."]="在 Twilight's Shroud 击败霸主 Kilgar，并将他的头颅交给 Da'grosh。",
["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Sergeant Riftan."]="在 Twilight's Shroud 击败霸主 Kilgar，并将他的头颅交给 Riftan 中士。",
["Deliver Chogg's head to the ogre city to the north."]="将 Chogg 的头颅送到北方的食人魔城市。",
["Deliver the Abominable Head to Master Apothecary Faranell within the Undercity."]="将憎恶的头颅交给幽暗城的大药剂师法拉尼尔。",
["Deliver the head of Chogg to Tran'gul in Rog'mar."]="将 Chogg 的头颅交给 Rog'mar 的 Tran'gul。",
["Deliver the missive to Krom'rosh at Rog'mar."]="将密信交给 Rog'mar 的 Krom'rosh。",
["Destroy 5 Twilight Ritual Circles found throughout the caves underneath Sunnyglade."]="摧毁 Sunnyglade 地下洞穴中的 5 个暮光仪式法阵。",
["Escort Sergeant Danneth out of the Serpent's Coil caves and back to Nethergarde Keep."]="护送 Danneth 中士离开 Serpent's Coil 洞穴，返回守望堡。",
["Explore Shen'dralas in an effort to find other pylons like the one you found."]="探索 Shen'dralas，寻找与之前发现的水晶塔相似的其他水晶塔。",
["Explore the Vile Reef and find the cavern entrance."]="探索 Vile Reef，寻找洞穴入口。",
["Find Da'grosh in the hills west of Rog'mar."]="在 Rog'mar 西边的山丘寻找 Da'grosh。",
["Find Loremaster Dibbs in Southshore and bring him the Savage Coast Report Bundle."]="找到南海镇的博学者迪布斯，将荆棘谷海岸报告交给他。",
["Find Sergeant Danneth somewhere in the Serpent's Coil caverns southeast of Nethergarde Keep."]="在守望堡东南方的 Serpent's Coil 洞穴寻找 Danneth 中士。",
["Find Sergeant Riftan near the Twilight's Shroud to the west."]="在西方 Twilight's Shroud 附近寻找 Riftan 中士。",
["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village."]="在影牙城堡找到 Xelthos 号角，然后将其放入焚木村附近 C 的秘密交接点。",
["Find The Talisman of Kazdor inside of Zul'Farrak. Then, bring it to Fahrad at Ravenholdt Manor. You must complete the job alone."]="在祖尔法拉克找到卡兹多尔护符，交给拉文霍德庄园的 Fahrad。你必须独自完成任务。",
["Find Veyric Thundervein in Arathi Highlands."]="在阿拉希高地寻找 Veyric Thundervein。",
["Find Woodwyrd in the Forlorn Gardens at Shen'dralas in the Desolace."]="在凄凉之地 Shen'dralas 的荒弃花园寻找 Woodwyrd。",
["Find missing ogres in the caves beneath Sunnyglade for Clubtoe."]="在 Sunnyglade 地下洞穴寻找失踪的食人魔，向 Clubtoe 复命。",
["Find someone in Farholde Keep who may know about the mould."]="在 Farholde Keep 寻找可能知道模具下落的人。",
["Find someone in Rog'mar who may know about the mould."]="在 Rog'mar 寻找可能知道模具下落的人。",
["Find the missing Kor'kron Elites."]="找到失踪的库卡隆精英。",
["Find the owner of the Ancient Petrified Leaf. Good luck, <Name>; It's a big world."]="找到远古石叶的主人。祝你好运，<Name>；世界很大。",
["Gather 10 Brinescale Tridents from Brinescale Skirmishers."]="从 Brinescale 散兵身上收集 10 把 Brinescale 三叉戟。",
["Inject the Hissing Serum into the system above Othmar's body for Master Apothecary Faranell."]="为大药剂师法拉尼尔将嘶鸣血清注入 Othmar 遗体上方的装置。",
["Investigate Fenris Isle to the east and learn the fate of the Earthen Ring traveling party."]="调查东面的芬里斯岛，了解大地之环旅行队的遭遇。",
["Investigate Fenris Keep to the north and attempt to locate the missing member of the Earthen Ring party."]="调查北面的芬里斯城堡，寻找失踪的大地之环成员。",
["Investigate the Forlorn Gardens near Shen'dralas and then return to Mithera at the nearby temple."]="调查 Shen'dralas 附近的荒弃花园，然后回到附近神殿向 Mithera 复命。",
["Kill 12 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands."]="击杀 12 只沼泽爬行者，然后返回湿地向绿衣守护者 Rethiel 复命。",
["Kill 15 Kurzen Jungle Fighters.  Return to Sergeant Yohwa at the Rebel Camp."]="击杀 15 名库尔森丛林战士，然后回反抗军营地向 Yohwa 中士复命。",
["Kill 5 Empowered Brutes and 10 Twilight Ritualists then return to Clubtoe in Sunnyglade."]="击杀 5 名强化蛮兵和 10 名暮光仪祭师，然后回 Sunnyglade 向 Clubtoe 复命。",
["Kill 7 Twilight Maulers and 7 Twilight Firecallers for Clugfist in Bolder'ok."]="为 Bolder'ok 的 Clugfist 击杀 7 名暮光斗士和 7 名暮光唤火者。",
["Kill Chogg'Zac in the Sunnyglade cave and collect their heads for Clubtoe."]="在 Sunnyglade 洞穴击杀 Chogg'Zac，收集他们的头颅交给 Clubtoe。",
["Locate Magister Kirandis inside the temple of Shen'dralas."]="在 Shen'dralas 的神殿找到魔导师 Kirandis。",
["Log"]="日志",
["Meet Sully McCleary in Dustwallow Marsh and learn more about your mission."]="在尘泥沼泽会见萨莉·麦克利里，了解任务详情。",
["Obtain a Necrotic Runestone from Maleki the Pallid in Stratholme, then find the Rotting Dwarf Corpse near the Undercroft in southwestern Eastern Plaguelands."]="从斯坦索姆的苍白的玛勒基处取得亡灵符文石，然后在东瘟疫之地西南部的墓穴附近寻找腐烂的矮人尸体。",
["Recover The Coldbringer's Eye from Razorfen Downs."]="从剃刀高地取回寒冰使者之眼。",
["Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore."]="从黑石深渊取回火焰之地碎片，交给莫高雷的 Alaana Stormwalker。",
["Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade."]="取回玛格拉姆和吉尔吉斯村庄守卫的水晶塔碎片，交给 Mordent Evenshade。",
["Report to Krom'rosh in Rog'mar."]="向 Rog'mar 的 Krom'rosh 报到。",
["Report your findings to Master Apothecary Faranell in Undercity."]="向幽暗城的大药剂师法拉尼尔报告调查结果。",
["Rescue 5 Farholde Scouts within the Twilight's Shroud for Sergeant Riftan."]="在 Twilight's Shroud 解救 5 名 Farholde 斥候，向 Riftan 中士复命。",
["Rescue 5 Rog'mar Scouts within the Twilight's Shroud for Da'grosh."]="在 Twilight's Shroud 解救 5 名 Rog'mar 斥候，向 Da'grosh 复命。",
["Retrieve 25 Twilight Charms from Twilight Shadowmancers and Twilight Neophytes in Sunnyglade for Ashe Amberhall in Farholde Keep."]="从 Sunnyglade 的暮光暗法师和暮光新兵身上取回 25 个暮光护符，交给 Farholde Keep 的 Ashe Amberhall。",
["Retrieve 3 Twilight Missives from Twilight Shadowmancers in Sunnyglade for Tran'gul in Rog'mar."]="从 Sunnyglade 的暮光暗法师身上取得 3 封暮光密信，交给 Rog'mar 的 Tran'gul。",
["Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."]="从腐皮豺狼人身上取得芬里斯岛钥匙，解救 Lumina Windsinger。",
["Return to Orphan Matron Aria in Dalaran and inform her of Sergeant Danneth's intentions to take in Randal."]="返回达拉然向孤儿监护人 Aria 说明 Danneth 中士打算收养 Randal。",
["Seek out a quilboar of significance at the Bristleback Retreat."]="在 Bristleback Retreat 寻找一位重要的野猪人。",
["Seek out the SI:7 agent stationed on Theramore Isle."]="寻找驻扎在塞拉摩岛的军情七处特工。",
["Slay 12 Meadowsbrook Farmhands, then return to Krom'rosh with news of your success."]="击杀 12 名 Meadowsbrook 农场工人，然后向 Krom'rosh 复命。",
["Slay 8 Farholde Priests and 12 Farholde Scouts south of the river."]="击杀河流以南的 8 名 Farholde 牧师和 12 名 Farholde 斥候。",
["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran."]="击杀巫医祖穆拉恩，将他的头颅交给达拉然的大法师兰达洛克。",
["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore."]="击杀巫医祖穆拉恩，将他的头颅交给莫高雷的 Mazu'kon。",
["Speak to Fahrad when you're ready to hear his plan."]="准备好听取计划时与 Fahrad 交谈。",
["Speak to Mathrengyl Bearwalker at the Cenarion Enclave in Darnassus."]="与达纳苏斯塞纳里奥区的 Mathrengyl Bearwalker 交谈。",
["Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."]="向亡灵哨兵 Baldren 询问最近经过瑟伯切尔的神秘大地之环旅人。",
["Speak with Katherine to learn more about Aeonas, and then find him in the Scarlet Monastery."]="与凯瑟琳交谈了解艾奥纳斯，然后在血色修道院找到他。",
["Speak with Lumina Windsinger in the Sepulcher."]="与瑟伯切尔的 Lumina Windsinger 交谈。",
["Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired."]="与 Shen'dralas 的 Mordent Evenshade 交谈，了解你修复的水晶。",
["Speak with Ott and ask him to forge your blade."]="与奥特交谈，请他锻造你的剑。",
["Speak with Sergeant Danneth at Nethergarde Keep."]="与守望堡的 Danneth 中士交谈。",
["Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."]="与乌尔卡中士交谈，了解奥卡兹岛的情况。",
["Speak with Trevan Rol in the Sepulcher and bring him the materials he requires."]="与瑟伯切尔的 Trevan Rol 交谈，并带给他所需材料。",
["Steal 6 Feed Satchels from the Alliance farm in Meadowsbrook then return to Krom'rosh."]="从 Meadowsbrook 的联盟农场偷取 6 个饲料袋，然后返回 Krom'rosh 处。",
["Summon a Twilight's Thrall from a conduit within the Twilight Shroud and capture it with Amberhall's Soulstone."]="从 Twilight Shroud 的导管召唤一个暮光仆从，用 Amberhall 的灵魂石捕获它。",
["Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.  You recall Ragged John talking about Windsor being dragged off to a prison."]="前往西北方黑石山并进入黑石深渊，查明温德索尔元帅的下落。你记得 Ragged John 说过温德索尔被拖进了监狱。",
["Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done. "]="前往菲拉斯的厄运之槌，从扭木区的 Wildspawn 萨特身上取得 15 份萨特之血，然后返回腐烂之痕向 Daio 复命。",
["Travel to Dire Maul to acquire a Felvine Seed from Alzzin the Wildshaper, an Ancient Memento from Prince Tortheldrin, and an Earthstone Diamond Pinky Ring from King Gordok, and bring them to Pix Xizzix in Booty Bay."]="前往厄运之槌，从奥兹恩处取得魔藤种子，从托塞德林王子处取得远古纪念品，从戈多克大王处取得土钻指环，交给藏宝海湾的 Pix Xizzix。",
["Travel to Nethergarde Keep in the Blasted Lands and locate Sergeant Danneth."]="前往诅咒之地的守望堡，找到 Danneth 中士。",
["Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."]="前往银松森林的瑟伯切尔，与 Trevan Rol 交谈，询问失踪的大地之环旅人。",
["Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment. "]="前往黑石山的采石场击杀 Pyron，完成后向 Thunderheart 复命。",
["Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."]="使用军情七处伪装工具，在塞拉摩法师塔窃听吉安娜和她的亲信。",
["Use the hide and charcoal to create a rubbing of the Third Troll Legend tablet."]="使用皮革和木炭拓印第三块巨魔传说石板。",
["Use the hide and charcoal to create rubbings of the tablets found in the Drowned City."]="使用皮革和木炭拓印沉没之城的石板。",
["Venture to Maraudon and recover a Vial of Earth Song Water and return it to Woodwyrd at the Forlorn Gardens in Desolace."]="前往玛拉顿取回一瓶大地之歌之水，交给凄凉之地荒弃花园的 Woodwyrd。",
["Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat in the Desolace. Kog'thug felt it worth reminding that the Blood of Agamaggan inside Razorfen Kraul would not be sufficient."]="前往剃刀高地取得阿迦玛甘的恶毒之血，交给凄凉之地 Bristleback Retreat 的 Kog'thug。剃刀沼泽中的阿迦玛甘之血不能代替。",
["Watch as Ott forges your blade."]="观看奥特锻造你的剑。",
