["-0 seconds on the casting time of your Chain Heal spell."]="-0 秒，减少你的连锁治疗法术的施法时间。",
["-0.1 sec to the casting time of your Flash Heal spell."]="-0.1 秒到你的快速治疗法术的施法时间。",
["-10 energy cost for your Slice and Dice ability."]="-10 切片和切块能力的能量消耗。",
["-2 rage cost to Intercept."]="-2 拦截的愤怒成本。",
["1% chance on a melee critical hit to call forth the spirit of Eskhandar to protect you in battle for 2 min. (Proc chance: 1%, 2m cooldown)"]="1% 近战暴击几率召唤艾斯坎达尔之魂，在战斗中保护你 2 分钟。 (触发几率：1%，2m冷却时间)",
["10% chance after casting Arcane Missiles, Fireball, or Frostbolt that your next spell with a casting time under 10 seconds cast instantly. (Proc chance: 10%)"]="在施放奥术飞弹、火球术或冰箭后，有 10% 的几率立即施放下一个施法时间低于 10 秒的法术。 （触发几率：10%）",
["10% chance of dealing 15 to 25 Nature damage on a successful melee attack. (Proc chance: 10%)"]="成功的近战攻击时，10% 几率造成 15 到 25 自然伤害。 (触发几率：10%)",
["15% increase to the total damage absorbed by Mana Shield."]="15 法力护盾吸收的总伤害增加%。",
["15% increased damage to your Eviscerate ability."]="15% 对你的剔骨能力造成的伤害提高。",
["20% chance after using an offensive ability requiring rage that your next offensive ability requires 5 less rage to use. (Proc chance: 20%)"]="20% 的几率在使用需要怒气的攻击能力后，你的下一个攻击能力需要 5 更少的怒气来使用。 （触发几率：20%）",
["20% chance that your heals on others will also heal you 10% of the amount healed. (Proc chance: 20%)"]="20% 你治愈他人的几率也会治愈你 10% 的治愈量。 （触发几率：20%）",
["20% chance to regain 100 mana when you cast a Judgement. (Proc chance: 20%)"]="当你施放审判时，20% 有几率恢复 100 法力。 （触发几率：20%）",
["4% chance on melee attack of restoring 30 energy. (Proc chance: 4%)"]="4%的近战攻击几率恢复30能量。 （触发几率：4%）",
["4% chance to parry the next attack after a block. (Proc chance: 4%)"]="4% 格挡后格挡下一次攻击的几率。 （触发几率：4%）",
["5% chance of dealing 30 to 50 Fire damage on a successful melee attack. (Proc chance: 10%)"]="成功的近战攻击时，5% 几率对 30 至 50 造成火焰伤害。 (触发几率：10%)",
["5% increased damage from your summoned pets' melee attacks and damage spells."]="5% 召唤宠物的近战攻击和伤害法术造成的伤害提高。",
["5% increased damage on your Immolate spell."]="5% 牺牲法术伤害提高。",
["After casting your Healing Wave or Lesser Healing Wave spell, gives you a 25% chance to gain Mana equal to 35% of the base cost of the spell. (Proc chance: 25%, 1s cooldown)"]="在施放你的治疗波或次级治疗波法术后，你有 25% 的几率获得相当于法术基本费用 35% 的法力。 (触发几率：25%，1的冷却时间)",
["Allows 15% of your Mana regeneration to continue while casting."]="施法时可以继续恢复 15% 的法力。",
