["When struck by a harmful spell, has a 7% chance of Silencing the caster for 3 sec. Can only occur once every 60 sec. (Proc chance: 7%, 1m cooldown)"]="当受到有害法术攻击时，有 7% 的几率使施法者沉默 3 秒。每 60 秒只能发生一次。 (触发几率：7%，1m冷却时间)",
["When struck in combat has a 2% chance of causing the attacker to flee in terror for 2 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="在战斗中被击中时，有 2% 的几率导致攻击者惊恐逃跑 2 秒。每 60 秒只能发生一次。 (触发几率：2%，1m冷却时间)",
["When struck in combat has a 2% chance of freezing the attacker in place for 3 sec. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="在战斗中被击中时，有 2% 的几率将攻击者冻结在原地 3 秒。每 60 秒只能发生一次。 (触发几率：2%，1m冷却时间)",
["When struck in combat has a 2% chance of shielding the wearer in a protective shield which will absorb 488 damage. Can only occur once every 60 sec. (Proc chance: 2%, 1m cooldown)"]="当在战斗中被击中时，有 2% 的几率用防护罩保护佩戴者，该防护罩将吸收 488 伤害。每 60 秒只能发生一次。 (触发几率：2%，1m冷却时间)",
["When struck in combat has a chance of returning 300 mana, 10 rage, or 40 energy to the wearer. (Proc chance: 2%)"]="在战斗中被击中时，有几率将 300 法力、10 怒气或 40 能量返回给佩戴者。 (触发几率：2%)",
["When struck in combat, has a 10% chance to remove a Disarm effect from yourself. Can only occur once every 60 sec. (Proc chance: 10%, 1m cooldown)"]="在战斗中被击中时，有 10% 的几率消除自己的缴械效果。每 60 秒只能发生一次。 (触发几率：10%，1m冷却时间)",
["When struck in combat, has a 5% chance to increase your movement speed by 10% for 8 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在战斗中被击中时，有 5% 的几率使你的移动速度提高 10%，持续 8 秒。每 60 秒只能发生一次。 (触发几率：5%，1m冷却时间)",
["When struck in combat, has a 5% chance to remove a Snare effect from yourself. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在战斗中被击中时，有 5% 的几率消除自己的圈套效果。每 60 秒只能发生一次。 (触发几率：5%，1m冷却时间)",
["When struck in combat, has a 8% chance to remove a Root effect from yourself. Can only occur once every 60 sec. (Proc chance: 8%, 1m cooldown)"]="在战斗中被击中时，有 8% 的几率消除自己的定身效果。每 60 秒只能发生一次。 (触发几率：8%，1m冷却时间)",
["When struck in melee combat, has a 5% chance of Disarming the attacker for 4 sec. Can only occur once every 60 sec. (Proc chance: 5%, 1m cooldown)"]="在近战战斗中被击中时，有 5% 的几率解除攻击者的武装，持续 4 秒。每 60 秒只能发生一次。 (触发几率：5%，1m冷却时间)",
["When struck in melee there is a 50% chance you will Fade for 4 sec. (Proc chance: 50%, 5s cooldown)"]="当在近战中被击中时，你有 50% 的几率会消失 4 秒。 (触发几率：50%，5的冷却时间)",
["When you cast a Healing Wave or Lesser Healing Wave, there is a 25% chance the target also receives a free Lightning Shield that causes 50 Nature damage to attacker on hit. (Proc chance: 25%)"]="当你施放治疗波或次级治疗波时，目标还有 25% 的几率获得免费的闪电护盾，对攻击者造成 50 自然伤害。 （触发几率：25%）",
["When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done by up to 160."]="当你的生命值低于 20% 时，在接下来的 5 秒内，对你施放的治疗法术会帮助你欺骗死亡，将治疗效果提高最多 160。",
