["You have a chance whenever you deal ranged damage to apply an Expose Weakness effect to the target. Expose Weakness increases the Ranged Attack Power of all attackers against that target by 450 for 7 sec."]="每当你造成远程伤害时，你就有机会对目标施加暴露弱点效果。暴露弱点使所有攻击者对该目标的远程攻击强度增加 450，持续 7 秒。",
["Your Backstab, Sinister Strike, and Hemorrhage critical hits cause you to regain 5 energy. (500ms cooldown)"]="你的背刺、险恶打击和出血暴击会让你恢复 5 能量。 (500ms 冷却时间)",
["Your Blizzard spell has a 30% chance to be uninterruptible."]="你的暴风雪法术有 30% 的几率不间断。",
