["Your Flash of Light and Holy Light spells have a chance to imbue your target with Holy Power. (Proc chance: 10%)"]="你的圣光闪现和圣光法术有一定几率为你的目标注入神圣力量。 （触发几率：10%）",
["Your Frostfire Bolt spell has a 10% increased chance to trigger Missile Barrage, gains 10% increased critical strike chance while your Combustion spell is active, and has a 10% increased chance to trigger Fingers of Frost."]="你的霜火箭法术触发导弹弹幕的几率提高 10%，当你的燃烧法术激活时暴击几率提高 10%，并且触发冰霜之指的几率提高 10%。",
["Your Greater Heals now have a heal over time component equivalent to a rank 5 Renew."]="您的强效治疗现在具有相当于等级 5 更新的随时间治疗部分。",
["Your Healing Wave and Lesser Healing Wave spells have a chance to imbue your target with Totemic Power. (Proc chance: 10%)"]="你的治疗波和次级治疗波法术有一定几率为你的目标注入图腾力量。 （触发几率：10%）",
["Your Healing Wave will now jump to additional nearby targets. Each jump reduces the effectiveness of the heal by 80%, and the spell will jump to up to two additional targets."]="你的治疗波现在会跳到附近的其他目标。每次跳跃都会使治疗效果降低 80%，并且该法术最多会跳跃到两个额外目标。",
