["Your Rejuvenation ticks have a chance to restore 60 mana, 8 energy, or 2 rage to your target."]="你的回春蜱有机会为你的目标恢复 60 法力、8 能量或 2 怒气。",
["Your Shadow Bolts now have a chance to heal you for 270 to 330."]="你的暗影箭现在有机会治愈你 270 到 330。",
["Your attacks have a chance to increase your Attack Power by 40 and your healing spells have a chance to increase your Intellect by 20 for 15 sec. (Proc chance: 10%)"]="你的攻击有机会使你的攻击强度增加 40，你的治疗法术有机会使你的智力增加 20，持续 15 秒。 (触发几率：10%)",
["Your damage spells have a chance to cause your target to take up to 200 increased damage from subsequent spells. (Proc chance: 20%)"]="你的伤害法术有一定几率使你的目标因后续法术而受到最多 200 的伤害。 （触发几率：20%）",
["Your damage spells have a chance to displace you, causing the next spell cast to generate no threat. (Proc chance: 15%)"]="你的伤害法术有机会取代你，导致下一次施放的法术不会产生任何威胁。 （触发几率：15%）",
["Your finishing moves now refund 30 energy on a Miss, Dodge, Block, or Parry."]="现在，你的终结动作会在未击中、闪避、格挡或招架时返还 30 能量。",
["Your initial cast and Regrowth ticks will increase the maximum health of your target by up to 50, stacking up to 7 times."]="您的初始施法和再生滴答数将使目标的最大生命值增加最多 50，最多可叠加 7 次。",
["Your melee and ranged autoattacks have a 5% chance to energize you for 200 mana. (Proc chance: 5%)"]="你的近战和远程自动攻击有 5% 的几率为你提供 200 法力值。 （触发几率：5%）",
["Your normal melee swings have a chance to Invigorate you, healing you for 90 to 110."]="你的正常近战挥动有机会为你注入活力，为你治疗 90 至 110。",
